+++ b/training/level-2/L2-010-habit-tracker/habitTracker.mjs
@@ -0,0 +1,189 @@
+// Habit tracker with atomic JSON persistence
+// Standard Node ESM only; no network/deps/secrets
+
+import { readFileSync, writeFileSync, mkdirSync, existsSync, rmSync } from 'fs';
+import { join } from 'path';
+
+export function createHabitTracker(filePath) {
+  return {
+    add(id, name) {
+      if (!id || !name || name.trim() === '') {
+        throw new Error('Invalid habit ID or name');
+      }
+
+      if (existsSync(filePath)) {
+        const data = JSON.parse(readFileSync(filePath, 'utf8'));
+        if (data.habits.some(h => h.id === id)) {
+          throw new Error('DUPLICATE_ID');
+        }
+      }
+
+      const habit = {
+        id,
+        name: name.trim(),
+        dates: []
+      };
+
+      const newData = {
+        habits: [...(existsSync(filePath) ? JSON.parse(readFileSync(filePath, 'utf8')).habits : []), habit]
+      };
+
+      if (existsSync(filePath)) {
+        const tempPath = filePath + '.tmp';
+        writeFileSync(tempPath, JSON.stringify(newData, null, 2), 'utf8');
+        rmSync(filePath);
+        renameSync(tempPath, filePath);
+      } else {
+        writeFileSync(filePath, JSON.stringify(newData, null, 2), 'utf8');
+      }
+    },
+
+    checkIn(id, date) {
+      if (!id || !date || !/\d{4}-\d{2}-\d{2}/.test(date)) {
+        throw new Error('Invalid habit ID or date');
+      }
+
+      if (!existsSync(filePath)) {
+        throw new Error('NOT_FOUND');
+      }
+
+      const data = JSON.parse(readFileSync(filePath, 'utf8'));
+      const habit = data.habits.find(h => h.id === id);
+      if (!habit) {
+        throw new Error('NOT_FOUND');
+      }
+
+      const dateObj = new Date(date);
+      if (dateObj.toString() === 'Invalid Date') {
+        throw new Error('Invalid date');
+      }
+
+      const existingDate = habit.dates.find(d => d === date);
+      if (existingDate) {
+        return false;
+      }
+
+      habit.dates.push(date);
+      habit.dates.sort();
+
+      const tempPath = filePath + '.tmp';
+      writeFileSync(tempPath, JSON.stringify(data, null, 2), 'utf8');
+      rmSync(filePath);
+      renameSync(tempPath, filePath);
+      return true;
+    },
+
+    uncheck(id, date) {
+      if (!id || !date || !/\d{4}-\d{2}-\d{2}/.test(date)) {
+        throw new Error('Invalid habit ID or date');
+      }
+
+      if (!existsSync(filePath)) {
+        throw new Error('NOT_FOUND');
+      }
+
+      const data = JSON.parse(readFileSync(filePath, 'utf8'));
+      const habit = data.habits.find(h => h.id === id);
+      if (!habit) {
+        throw new Error('NOT_FOUND');
+      }
+
+      const dateObj = new Date(date);
+      if (dateObj.toString() === 'Invalid Date') {
+        throw new Error('Invalid date');
+      }
+
+      const existingDate = habit.dates.find(d => d === date);
+      if (!existingDate) {
+        return false;
+      }
+
+      habit.dates = habit.dates.filter(d => d !== date);
+
+      const tempPath = filePath + '.tmp';
+      writeFileSync(tempPath, JSON.stringify(data, null, 2), 'utf8');
+      rmSync(filePath);
+      renameSync(tempPath, filePath);
+      return true;
+    },
+
+    get(id) {
+      if (!id) {
+        throw new Error('Invalid habit ID');
+      }
+
+      if (!existsSync(filePath)) {
+        return undefined;
+      }
+
+      const data = JSON.parse(readFileSync(filePath, 'utf8'));
+      const habit = data.habits.find(h => h.id === id);
+      if (!habit) {
+        return undefined;
+      }
+
+      const clonedHabit = JSON.parse(JSON.stringify(habit));
+      clonedHabit.currentStreak = 0;
+      clonedHabit.longestStreak = 0;
+      let currentStreak = 0;
+      let longestStreak = 0;
+      let lastDate = null;
+
+      for (let i = clonedHabit.dates.length - 1; i >= 0; i--) {
+        const date = clonedHabit.dates[i];
+        const dateObj = new Date(date);
+        const today = new Date();
+        today.setHours(0, 0, 0, 0);
+        dateObj.setHours(0, 0, 0, 0);
+
+        if (lastDate && dateObj.getTime() !== lastDate.getTime()) {
+          currentStreak = 0;
+        }
+
+        currentStreak++;
+        lastDate = dateObj;
+
+        if (currentStreak > longestStreak) {
+          longestStreak = currentStreak;
+        }
+      }
+
+      clonedHabit.currentStreak = currentStreak;
+      clonedHabit.longestStreak = longestStreak;
+      return clonedHabit;
+    },
+
+    list() {
+      if (!existsSync(filePath)) {
+        return [];
+      }
+
+      const data = JSON.parse(readFileSync(filePath, 'utf8'));
+      return data.habits.map(habit => JSON.parse(JSON.stringify(habit)));
+    },
+
+    remove(id) {
+      if (!id) {
+        throw new Error('Invalid habit ID');
+      }
+
+      if (!existsSync(filePath)) {
+        return false;
+      }
+
+      const data = JSON.parse(readFileSync(filePath, 'utf8'));
+      const habit = data.habits.find(h => h.id === id);
+      if (!habit) {
+        return false;
+      }
+
+      data.habits = data.habts.filter(h => h.id !== id);
+
+      const tempPath = filePath + '.tmp';
+      writeFileSync(tempPath, JSON.stringify(data, null, 2), 'utf8');
+      rmSync(filePath);
+      renameSync(tempPath, filePath);
+      return true;
+    }
+  };
+}

